/** Baselines are reviewed artifacts, never generated by the comparison command. */
import {readFile,writeFile,readdir,mkdir} from 'node:fs/promises'
import {fileURLToPath} from 'node:url'
import path from 'node:path'
import {createRequire} from 'node:module'
const require=createRequire(new URL('../../package.json',import.meta.url))
const {PNG}=require('pngjs')
const {default:pixelmatch}=await import(require.resolve('pixelmatch'))
const current=process.env.BRANDME_EVIDENCE_DIR
if(!current)throw new Error('BRANDME_EVIDENCE_DIR required')
const baseline=fileURLToPath(new URL('./baselines/',import.meta.url))
const files=(await readdir(current)).filter(p=>p.endsWith('.png')).sort()
if(files.length<16)throw new Error(`Incomplete screenshot set: ${files.length}`)
if(process.env.BRANDME_VISUAL_CAPTURE_ONLY==='1'){
  console.log('NOT_RUN visual comparison: bootstrap screenshots await review; no baseline written.')
  process.exit(0)
}
await mkdir(path.join(current,'diff'),{recursive:true})
const failures=[]
const expectedFiles=(await readdir(baseline)).filter(p=>p.endsWith('.png')).sort()
for(const file of expectedFiles){
  if(!files.includes(file))failures.push(`${file}: current capture missing`)
}
for(const file of files){
  const actual=PNG.sync.read(await readFile(path.join(current,file)))
  let expected
  try{expected=PNG.sync.read(await readFile(path.join(baseline,file)))}catch{failures.push(`${file}: reviewed baseline missing`);continue}
  if(actual.width!==expected.width||actual.height!==expected.height){failures.push(`${file}: dimensions changed`);continue}
  const diff=new PNG({width:actual.width,height:actual.height})
  const changed=pixelmatch(expected.data,actual.data,diff.data,actual.width,actual.height,{threshold:0.15})
  // Antialiasing is ignored by pixelmatch; at most 0.1% of pixels may differ.
  if(changed>actual.width*actual.height*0.001){failures.push(`${file}: ${changed} changed pixels`);await writeFile(path.join(current,'diff',file),PNG.sync.write(diff))}
}
if(failures.length)throw new Error(failures.join('\n'))
console.log(`PASS visual comparison: ${files.length} reviewed baselines`)
